  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00086",
          "explanation": "The doctor provided a concrete script to reduce family conflict with the grandmother.",
          "quote": "你可以这样跟婆婆解释"
        },
        {
          "event_id": "lite_evt_00100",
          "explanation": "The family reported that the intervention changed the grandmother’s behavior.",
          "quote": "没有再催我两个一起喂了"
        }
      ],
      "completion": "complete",
      "explanation": "HO1 was triggered by the anxious mother and caregiver disagreement; the doctor used validating, non-blaming communication and gave a practical script that visibly reduced household pressure.",
      "ho_id": "HO1",
